import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        final int N = 505;
        int[] blok = new int[N];
        int[] sum = new int[N];
        int[][] binom = new int[N][N];
        long[][] dp = new long[N][N];
        long[][] ways = new long[N][N];

        // Initialize binom
        for (int i = 0; i < N; i++) {
            binom[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                binom[i][j] = (binom[i - 1][j] + binom[i - 1][j - 1]) % mod;
            }
        }

        // Helper functions
        // add_mod
        class ModUtils {
            static void addMod(int[] a, int b) {
                a[0] += b;
                if (a[0] >= mod) a[0] -= mod;
            }

            static int mulMod(int a, int b) {
                return (int)((long)a * b % mod);
            }

            static int c2(int x) {
                return (int)((long)x * (x + 1) / 2 % mod);
            }
        }

        // Initialize blok and sum
        for (int i = 0; i < N; i++) {
            blok[i] = 0;
            sum[i] = 0;
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                dp[i][j] = 0;
                ways[i][j] = 0;
            }
        }

        // Compute blok and sum
        for (int x = 1; x <= m; x++) {
            for (int i = 1; i <= x; i++) {
                int temp1 = ModUtils.mulMod(blok[i - 1], ModUtils.mulMod(blok[x - i], binom[x - 1][i - 1]));
                int[] temp1Arr = new int[]{0};
                ModUtils.addMod(temp1Arr, temp1);
                blok[x] = (blok[x] + temp1Arr[0]) % mod;

                int temp2 = ModUtils.mulMod(ModUtils.c2(i - 1), ModUtils.mulMod(blok[x - i], binom[x - 1][i - 1]));
                int[] temp2Arr = new int[]{0};
                ModUtils.addMod(temp2Arr, temp2);
                temp2Arr[0] = (temp2Arr[0]) % mod;
                int temp2Val = temp2Arr[0];

                int temp2Sum = ModUtils.mulMod(temp2Val, (x + 1));
                int[] temp2SumArr = new int[]{0};
                ModUtils.addMod(temp2SumArr, temp2Sum);
                sum[x] = (sum[x] + temp2SumArr[0]) % mod;

                int temp3 = ModUtils.mulMod(sum[i - 1], ModUtils.mulMod(blok[x - i], binom[x - 1][i - 1]));
                int[] temp3Arr = new int[]{0};
                ModUtils.addMod(temp3Arr, temp3);
                int temp3Val = temp3Arr[0];

                int temp3Sum = ModUtils.mulMod(temp3Val, (x + 1));
                int[] temp3SumArr = new int[]{0};
                ModUtils.addMod(temp3SumArr, temp3Sum);
                sum[x] = (sum[x] + temp3SumArr[0]) % mod;

                int temp4 = ModUtils.mulMod(sum[x - i], ModUtils.mulMod(blok[i - 1], binom[x - 1][i - 1]));
                int[] temp4Arr = new int[]{0};
                ModUtils.addMod(temp4Arr, temp4);
                int temp4Val = temp4Arr[0];

                int temp4Sum = ModUtils.mulMod(temp4Val, (x + 1));
                int[] temp4SumArr = new int[]{0};
                ModUtils.addMod(temp4SumArr, temp4Sum);
                sum[x] = (sum[x] + temp4SumArr[0]) % mod;
            }
            blok[x] = (int)((long)blok[x] * (x + 1) % mod);
        }

        // Initialize ways
        ways[0][0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                for (int sz = 1; sz <= i; sz++) {
                    int temp1 = ModUtils.mulMod(ways[i - sz][j - 1], ModUtils.mulMod(blok[sz], binom[m - i + sz][sz]));
                    int[] temp1Arr = new int[]{0};
                    ModUtils.addMod(temp1Arr, temp1);
                    ways[i][j] = (ways[i][j] + temp1Arr[0]) % mod;

                    int temp2 = ModUtils.mulMod(ways[i - sz][j - 1], ModUtils.mulMod(sum[sz], binom[m - i + sz][sz]));
                    int[] temp2Arr = new int[]{0};
                    ModUtils.addMod(temp2Arr, temp2);
                    dp[i][j] = (dp[i][j] + temp2Arr[0]) % mod;

                    int temp3 = ModUtils.mulMod(dp[i - sz][j - 1], ModUtils.mulMod(blok[sz], binom[m - i + sz][sz]));
                    int[] temp3Arr = new int[]{0};
                    ModUtils.addMod(temp3Arr, temp3);
                    dp[i][j] = (dp[i][j] + temp3Arr[0]) % mod;
                }
            }
        }

        int ans = 0;
        int zero = n - m;
        for (int i = 1; i <= m; i++) {
            int lef = zero - (i - 1);
            if (lef >= 0) {
                int temp = ModUtils.mulMod(dp[m][i], binom[i + lef][lef]);
                int[] tempArr = new int[]{0};
                ModUtils.addMod(tempArr, temp);
                ans = (ans + tempArr[0]) % mod;
            }
        }

        System.out.println(ans);
        sc.close();
    }
}
